#include <bits/stdc++.h>using namespace std;#define int long long#define double long double int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int m, n, k, s;    cin >> n >> m >> k >> s;    vector<vector<int>> goods(n + 1);    for (int i = 1; i <= n; i++) {        int g;        cin >> g;        goods[g].push_back(i);    }    vector<vector<int>> adj(n + 1, vector<int>());    for (int i = 0; i < m; i++) {        int u, v;        cin >> u >> v;        adj[u].push_back(v);        adj[v].push_back(u);    }    vector<vector<int>> distance(n + 1, vector<int>(k + 1, -1));    for (int i = 1; i <= k; i++) {        queue<int> q;        for (int town : goods[i]) {            q.push(town);            distance[town][i] = 0;        }        while (!q.empty()) {            int node = q.front();            q.pop();            for (int neighbor : adj[node]) {                if (distance[neighbor][i] == -1) {                    distance[neighbor][i] = distance[node][i] + 1;                    q.push(neighbor);                }            }        }    }     for (int i = 1; i <= n; i++) {        vector<int> costs;        for (int j = 1; j <= k; j++) {            if (distance[i][j] != -1)                costs.push_back(distance[i][j]);        }        sort(costs.begin(), costs.end());         int total_cost = 0;        for (int j = 0; j < s; j++) {            total_cost += costs[j];        }        cout << total_cost << " ";    }     return 0;}